"use client";

import Image from "next/image";
import Link from "next/link";

import {
  motion,
  useReducedMotion,
} from "motion/react";

import {
  ArrowUpRight,
} from "lucide-react";

import clsx from "clsx";

import type { Product } from "@/types/content";

import styles from "./ProductCard.module.css";

type Props = {
  product: Product;
  priority?: boolean;
};

const brandNames: Record<
  string,
  string
> = {
  kubota: "KUBOTA",
  kobelco: "KOBELCO",
  bull: "BULL",
};

const categoryNames = {
  agricola: "Agricultura",
  construccion: "Construcción",
  implementos: "Implementos",
};

export default function ProductCard({
  product,
  priority = false,
}: Props) {
  const reduceMotion =
    useReducedMotion();

  const image =
    product.images[0];

  const brandId =
    product.brandId
      ?.toLowerCase()
      .trim();

  const brandName =
    brandNames[brandId] ??
    product.brandId?.toUpperCase() ??
    "MORGILLO";

  return (
    <motion.article
      className={clsx(
        styles.card,
        styles[
          `category-${product.category}`
        ],
        styles[
          `brand-${brandId}`
        ],
      )}
      initial={
        reduceMotion
          ? false
          : {
              opacity: 0,
              y: 28,
            }
      }
      whileInView={
        reduceMotion
          ? undefined
          : {
              opacity: 1,
              y: 0,
            }
      }
      viewport={{
        once: true,
        amount: 0.18,
      }}
      transition={{
        duration: 0.55,
        ease: [
          0.16,
          1,
          0.3,
          1,
        ],
      }}
    >
      <Link
        href={`/maquinaria/${product.slug}`}
        className={styles.link}
      >
        {/* =========================================
            IMAGE
        ========================================== */}

        <div className={styles.media}>
          <div
            className={styles.technicalLines}
            aria-hidden="true"
          >
            <span />
            <span />
            <span />
          </div>

          {image ? (
            <Image
              src={image.url}
              alt={image.alt}
              fill
              priority={priority}
              sizes="
                (max-width: 640px) 100vw,
                (max-width: 960px) 50vw,
                33vw
              "
              className={styles.image}
            />
          ) : (
            <div className={styles.imageFallback}>
              <span>Imagen pendiente</span>

              <strong>M</strong>
            </div>
          )}

          <span className={styles.brand}>
            <i />
            {brandName}
          </span>

          <span className={styles.category}>
            {
              categoryNames[
                product.category
              ]
            }
          </span>

          <span
            className={styles.brandAccent}
            aria-hidden="true"
          />
        </div>

        {/* =========================================
            CONTENT
        ========================================== */}

        <div className={styles.content}>
          <div className={styles.meta}>
            <span>
              Equipo
            </span>

            {product.mock && (
              <span className={styles.demo}>
                Demo
              </span>
            )}
          </div>

          <h3>{product.name}</h3>

          {product.model && (
            <p className={styles.model}>
              {product.model}
            </p>
          )}

          {/* =========================================
              SPECS
          ========================================== */}

          {product.specifications.length >
            0 && (
            <dl className={styles.specs}>
              {product.specifications
                .slice(0, 2)
                .map((spec) => (
                  <div
                    key={spec.label}
                  >
                    <dt>
                      {spec.label}
                    </dt>

                    <dd>
                      {spec.value}
                      {spec.unit
                        ? ` ${spec.unit}`
                        : ""}
                    </dd>
                  </div>
                ))}
            </dl>
          )}

          {/* =========================================
              ACTION
          ========================================== */}

          <div className={styles.action}>
            <span>
              Ver equipo
            </span>

            <span
              className={styles.actionIcon}
              aria-hidden="true"
            >
              <ArrowUpRight
                size={17}
                strokeWidth={1.8}
              />
            </span>
          </div>
        </div>
      </Link>
    </motion.article>
  );
}